const root = $input.first().json;
const b = (root.body && typeof root.body === 'object') ? root.body : root;
const admin_body = (b.admin_body || b.text || b.message || '').toString();
const admin_whatsapp = (b.admin_whatsapp || b.from || '').toString();
const respond_to = (b.respond_to || admin_whatsapp).toString();
const canal = (b.canal || '').toString();
const session_id = (b.session_id || '').toString();
if (!admin_body) { return [{ json: { _error: 'sin_texto' } }]; }
return [{ json: { admin_body, admin_whatsapp, respond_to, canal, session_id } }];

const adminBody = $('Preparar').first().json.admin_body;
const system = `Eres el asistente administrativo de Bejauha (estudio de yoga). Las administradoras escriben en lenguaje natural para gestionar clases. Devuelve SOLO un objeto JSON con la intencion, sin texto extra.\nAcciones:\n- \"asistencia\": alguien asistio a clase.\n- \"recarga\": alguien pago/compro clases (sumar).\n- \"consulta\": preguntan cuantas clases le quedan a alguien.\n- \"ajuste\": fijar el saldo a un numero exacto.\n- \"otro\": saludo/ayuda/no entendido.\nCampos: { \"accion\": \"...\", \"cliente\": \"<nombre o telefono mencionado>\", \"cantidad\": <numero o null>, \"respuesta_libre\": \"<solo si accion=otro, respuesta breve y calida>\" }\nEjemplos:\n\"Laura asistio\" -> {\"accion\":\"asistencia\",\"cliente\":\"Laura\",\"cantidad\":null}\n\"Pedro pago 8 clases\" -> {\"accion\":\"recarga\",\"cliente\":\"Pedro\",\"cantidad\":8}\n\"cuantas le quedan a Ana?\" -> {\"accion\":\"consulta\",\"cliente\":\"Ana\",\"cantidad\":null}`;
const openai_body = {
  model: 'gpt-4o',
  temperature: 0,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: system },
    { role: 'user', content: adminBody }
  ]
};
return [{ json: { openai_body } }];

let p={};try{p=JSON.parse($json.choices[0].message.content);}catch(e){p={accion:'otro',respuesta_libre:'No entendi, puedes decir por ejemplo: "Laura asistio" o "Pedro pago 8".'};}
const accion=(p.accion||'otro').toLowerCase();
const clienteRef=(p.cliente||'').toString().trim();
const cantidad=(p.cantidad===null||p.cantidad===undefined)?null:Number(p.cantidad);
const canalIn=($('Preparar').first().json.canal||'').toString();
const TEST_PHONE='+573000000001';
let raw=$('Leer contactos').all().map(i=>i.json);
let rows=(raw.length===1 && Array.isArray(raw[0]))?raw[0]:raw;
rows=rows.filter(r=>r && (r.full_name||r.phone));
const norm=s=>(s||'').toString().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').trim();
const tel10=s=>(s||'').toString().replace(/\D/g,'').slice(-10);
const refIsPhone=/\d{7,}/.test(clienteRef);
const refTokens=norm(clienteRef).split(/\s+/).filter(Boolean);
let matches=[];
if(clienteRef){if(refIsPhone){const t=tel10(clienteRef);matches=rows.filter(r=>tel10(r.phone)===t);}else{matches=rows.filter(r=>{const full=norm(r.full_name);return refTokens.every(tok=>full.includes(tok));});}}
let needs_update=false,contact_id=null,nuevo_saldo=null,admin_text='';
let disparar_recordatorio=false,recordatorio_cliente='',telefono57='';
const out={accion,clienteRef,cantidad};
if(accion==='otro'){admin_text=p.respuesta_libre||'No entendi la accion. Puedes decir "Laura asistio", "Pedro pago 8" o "cuantas le quedan a Ana?".';}
else if(!clienteRef){admin_text='No identifique a la persona. Dime el nombre o el telefono.';}
else if(matches.length===0){admin_text='No encontre a "'+clienteRef+'" en la base. Confirmas el nombre o el telefono?';}
else if(matches.length>1){admin_text='Hay varias personas con "'+clienteRef+'": '+matches.map(m=>(m.full_name||'')+' ('+tel10(m.phone)+')').join(', ')+'. A cual te refieres? Dame el telefono.';}
else{const r=matches[0];contact_id=r.id;const nombre=(r.full_name||'').trim();const primer=nombre.split(/\s+/)[0]||'';telefono57=(r.phone||'').toString();const servicio=(r.service_type||'').toString();const tipo=norm(servicio);const saldo=parseInt((r.clases_restantes===null||r.clases_restantes===undefined)?0:r.clases_restantes,10)||0;const esPaquete=(tipo==='paquete'||tipo.startsWith('paquete'));
if(accion==='consulta'){if(esPaquete)admin_text=nombre+' tiene '+saldo+' clase(s) restante(s).';else admin_text=nombre+' es plan '+(servicio||'(sin servicio)')+', no maneja saldo de clases (solo los paquetes descuentan).';}
else if(accion==='asistencia'){if(esPaquete){nuevo_saldo=Math.max(0,saldo-1);needs_update=true;admin_text='Registre la asistencia de '+nombre+'. Le quedan '+nuevo_saldo+' clase(s).';if(nuevo_saldo===1){disparar_recordatorio=true;recordatorio_cliente='Hola '+primer+' 🌿 te queda 1 clase de tu paquete. Cuando quieras renovamos para que no pierdas el ritmo 💛';admin_text+=' (queda en 1 → se le enviaria recordatorio al cliente)';}}else{admin_text='Asistencia de '+nombre+' registrada. Es '+(servicio||'sin servicio')+', no se le descuentan clases (acceso permanente / sin paquete).';}}
else if(accion==='recarga'){if(!esPaquete){admin_text='Sumar/restar clases solo aplica a clientes de Paquete. '+nombre+' es '+(servicio||'sin servicio')+'.';}else if(cantidad===null){admin_text='Cuantas clases le sumo a '+nombre+'? Responde con el numero.';}else{nuevo_saldo=saldo+cantidad;needs_update=true;admin_text='Recarga aplicada a '+nombre+'. Saldo actual: '+nuevo_saldo+' clase(s).';}}
else if(accion==='ajuste'){if(!esPaquete){admin_text='Ajustar saldo solo aplica a Paquete. '+nombre+' es '+(servicio||'sin servicio')+'.';}else if(cantidad===null){admin_text='A que numero ajusto el saldo de '+nombre+'?';}else{nuevo_saldo=Math.max(0,cantidad);needs_update=true;admin_text='Listo, '+nombre+' queda con '+nuevo_saldo+' clase(s).';}}}
// En modo test SOLO se escribe si es el contacto de prueba; para reales, se simula.
const escribir = needs_update && (canalIn!=='test' || telefono57===TEST_PHONE);
return [{json:{...out,needs_update,escribir,contact_id,nuevo_saldo,admin_text,disparar_recordatorio,recordatorio_cliente,telefono57}}];

